parameters.jsCode:
const s = $('Set your site').first().json;
const pages = $('Collect the audited pages').first().json.pages || [];
const prev = {};
for (const item of $input.all()) {
  const r = item.json || {};
  const u = String(r['URL'] || '').trim();
  if (u) prev[u] = r;
}
const drop = Number(s.dropPoints);
const floor = Number(s.minScore);
const out = [];
for (const p of pages) {
  const was = prev[p.url];
  const beforeRaw = was === undefined ? null : Number(was['Overall']);
  const before = beforeRaw === null || Number.isNaN(beforeRaw) ? null : beforeRaw;
  const delta = before === null ? null : Number(p.overallScore) - before;
  const critical = Number(p.criticalCount || 0);
  let status;
  if (delta === null) status = 'first audit';
  else if (delta <= -drop) status = 'dropped';
  else if (delta >= drop) status = 'improved';
  else status = 'unchanged';
  const needsFix = status === 'dropped' || Number(p.overallScore) < floor || critical > 0;
  let reason;
  if (status === 'dropped') reason = 'fell ' + Math.abs(delta) + ' points since the last audit';
  else if (critical > 0) reason = critical + ' critical issue' + (critical === 1 ? '' : 's') + ' on the page';
  else if (Number(p.overallScore) < floor) reason = 'scores ' + p.overallScore + ', under your floor of ' + floor;
  else reason = 'nothing to fix';
  const issues = (p.issues || []).slice(0, 12).map(i =>
    '- [' + String(i.severity || 'issue') + ' / ' + String(i.pillar || '') + '] ' + String(i.message || '')
    + (i.recommendation ? '\n    recommended fix: ' + String(i.recommendation) : ''));
  out.push({ json: {
    url: p.url,
    pageTitle: p.pageTitle || '',
    pageType: p.pageType || '',
    grade: p.grade || '',
    overall: Number(p.overallScore),
    seo: Number(p.seoScore),
    geo: Number(p.geoScore),
    aeo: Number(p.aeoScore),
    issuesFound: Number(p.issuesFound || 0),
    critical: critical,
    before: before === null ? '' : before,
    change: delta === null ? '' : (delta > 0 ? '+' + delta : String(delta)),
    status: status,
    needsFix: needsFix,
    reason: reason,
    issueList: issues.join('\n'),
    schemaTypes: (p.schemaTypes || []).join(', ') || 'none',
    questionHeadings: Number(p.questionHeadings || 0),
    wordCount: Number(p.wordCount || 0)
  } });
}
out.sort((a, b) => (Number(b.json.needsFix) - Number(a.json.needsFix))
  || (b.json.critical - a.json.critical) || (a.json.overall - b.json.overall));
return out;

