const esc = s => String(s ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const t = $json;
const p = $('Decide what needs fixing').item.json;
const scores = 'overall ' + p.overall + '/100 (' + p.grade + ')'
