  + '\ud83d\udcca ' + esc(scores) + ' \u00b7 SEO ' + p.seo + ' \u00b7 GEO ' + p.geo + ' \u00b7 AEO ' + p.aeo + '\n'
  + '\u26a0 ' + esc(p.reason) + '\n\n'
  + '<i>' + esc(t['Why it matters']) + '</i>\n\n'
  + '<b>Steps</b> (' + esc(t['Effort']) + ')\n<pre>' + esc(String(t['Steps']).trim()) + '</pre>';
})() }}
